CREATE TABLE insights_maintenance (workspace_id TEXT NOT NULL, project_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('frozen','purging')), PRIMARY KEY(workspace_id,project_id));
ALTER TABLE insights_activity ADD COLUMN project_id TEXT;
ALTER TABLE insights_subscriptions ADD COLUMN project_id TEXT;
ALTER TABLE insights_notifications ADD COLUMN project_id TEXT;
ALTER TABLE insights_receipts ADD COLUMN project_id TEXT;
CREATE INDEX insights_activity_project ON insights_activity(workspace_id,project_id);
CREATE INDEX insights_subscriptions_project ON insights_subscriptions(workspace_id,project_id);
CREATE INDEX insights_notifications_project ON insights_notifications(workspace_id,project_id);
CREATE INDEX insights_receipts_project ON insights_receipts(workspace_id,project_id);
CREATE TRIGGER insights_activity_freeze_insert BEFORE INSERT ON insights_activity WHEN (EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id)) OR (EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=NEW.workspace_id AND project_id<>'' AND NEW.project_id IS NULL)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
CREATE TRIGGER insights_activity_freeze_update BEFORE UPDATE ON insights_activity WHEN ((EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=NEW.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=NEW.workspace_id AND project_id=NEW.project_id)) OR (EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=OLD.workspace_id AND project_id='') OR EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=OLD.workspace_id AND project_id=OLD.project_id))) OR (EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=NEW.workspace_id AND project_id<>'' AND NEW.project_id IS NULL) OR EXISTS(SELECT 1 FROM insights_maintenance WHERE workspace_id=OLD.workspace_id AND project_id<>'' AND OLD.project_id IS NULL)) BEGIN SELECT RAISE(ABORT,'scope frozen'); END;
